<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Holder\UserProfileUpdatedAtAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserProfileUpdatedAtAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserProfileUpdatedAtAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getUpdatedAt returns null on a freshly created holder.
     */
    public function testUpdatedAtNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileUpdatedAtAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isUpdatedAtAssigned());
        $this->assertNull($holder->getUpdatedAt());
    }
}
class ImplWithUserProfileUpdatedAtAttributeHolderUnitTest
{
    use UserProfileUpdatedAtAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedUpdatedAtRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultUpdatedAt();
    }
}
